python
def firstArrivalsThresholdFile(readings, k):
    a=readings
    out=[]
    seen=set()
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return sum(x>=k for x in out)


java
class Solution {
  public int firstArrivalsThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
